frappe.ui.form.on('TDS Product Specification', {
    setup: function(frm) {
        if (frm.doc.__islocal && !frm.doc.tds_sequence) {
            get_next_sequence(frm);
        }
    },
    
    refresh: function(frm) {
        frm.add_custom_button(__('Generate Version'), function() {
            generate_version(frm);
        }, __('Actions')).addClass('btn-primary');
        
        update_preview(frm);
    },
    
    product_item: function(frm) {
        if (frm.doc.product_item) {
            frappe.db.get_value('Item', frm.doc.product_item, 'item_code')
                .then(r => {
                    frm.set_value('item_code', r.message.item_code);
                    if (frm.doc.__islocal) get_next_sequence(frm);
                    update_preview(frm);
                });
        }
    }
});

// Get next sequence number from TDS Settings
function get_next_sequence(frm) {
    if (!frm.doc.item_code) return;
    
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'TDS Settings',
            filters: { item_code: frm.doc.item_code },
            fields: ['name', 'last_sequence_used']
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                // Existing record found
                const settings = r.message[0];
                const next_seq = (settings.last_sequence_used || 0) + 1;
                frm.set_value('tds_sequence', next_seq);
                update_sequence_in_settings(settings.name, next_seq);
            } else {
                // Create new TDS Settings record
                frappe.call({
                    method: 'frappe.client.insert',
                    args: {
                        doc: {
                            doctype: 'TDS Settings',
                            item_code: frm.doc.item_code,
                            last_sequence_used: 0
                        }
                    },
                    callback: function(r) {
                        frm.set_value('tds_sequence', 1);
                        update_sequence_in_settings(r.message.name, 1);
                    }
                });
            }
        }
    });
}

// Update sequence in TDS Settings
function update_sequence_in_settings(name, sequence) {
    frappe.call({
        method: 'frappe.client.set_value',
        args: {
            doctype: 'TDS Settings',
            name: name,
            fieldname: { last_sequence_used: sequence }
        }
    });
}

// Generate final version number
function generate_version(frm) {
    if (!validate_required_fields(frm)) return;
    
    const date_parts = frm.doc.approval_date.split('-');
    const version = `V1.${frm.doc.item_code}-Date:${date_parts[0].slice(-2)}/${date_parts[1]}/${date_parts[2]}*${String(frm.doc.tds_sequence).padStart(4, '0')}`;
    
    frm.set_value('tds_version', version);
    frappe.show_alert(__('Version generated successfully'));
}

// Validate required fields
function validate_required_fields(frm) {
    let valid = true;
    
    if (!frm.doc.item_code) {
        frappe.msgprint(__('Item Code is required'));
        valid = false;
    }
    if (!frm.doc.approval_date) {
        frappe.msgprint(__('Approval Date is required'));
        valid = false;
    }
    if (!frm.doc.tds_sequence) {
        frappe.msgprint(__('Sequence Number is required'));
        valid = false;
    }
    
    return valid;
}

// Update version preview
function update_preview(frm) {
    if (frm.doc.item_code && frm.doc.approval_date && frm.doc.tds_sequence) {
        const date_parts = frm.doc.approval_date.split('-');
        const preview = `Preview: V1.${frm.doc.item_code}-Date:${date_parts[0].slice(-2)}/${date_parts[1]}/${date_parts[2]}*${String(frm.doc.tds_sequence).padStart(4, '0')}`;
        
        if (!frm.fields_dict.version_preview) {
            frm.add_custom_field('version_preview', {
                fieldtype: 'Section Break',
                label: 'Version Preview',
                description: preview
            });
        } else {
            frm.set_df_property('version_preview', 'description', preview);
        }
    }
}
frappe.ui.form.on('TDS Product Specification', {
    before_workflow_action: function(frm) {
        if (frm.selected_workflow_action === 'Approve' && !frm.doc.approval_date) {
            frappe.call({
                method: 'frappe.utils.nowdate',
                callback: function(r) {
                    frm.set_value('approval_date', r.message);
                }
            });
        }
    }
});

frappe.ui.form.on('TDS Product Specification', {
    item: function(frm) {
        if (!frm.doc.item) {
            frm.set_value('product_code', null);
            return;
        }
        
        frappe.call({
            method: 'frappe.client.get_value',
            args: {
                'doctype': 'Item',
                'filters': {'name': frm.doc.item},
                'fieldname': ['product_code', 'item_code']  // Try multiple fields
            },
            callback: function(r) {
                let product_code = r.message.product_code || 
                                  r.message.item_code || 
                                  frm.doc.item.substring(0,4);  // Fallback
                frm.set_value('product_code', product_code);
                
                // If version depends on this, trigger update
                if (frm.doc.custom_version) {
                    frm.trigger('refresh');
                }
            }
        });
    }
});

frappe.ui.form.on('TDS Settings', {
    refresh: function(frm) {
        frm.add_custom_button(__('Generate Version'), function() {
            // Validate required fields exist
            if (!frm.doc.naming_series) {
                frappe.msgprint(__('Naming Series is required'));
                return;
            }
            if (!frm.doc.tds_version_counter) {
                frappe.msgprint(__('Version Counter is required'));
                return;
            }
            if (!frm.doc.item_code) {
                frappe.msgprint(__('Item Code is required'));
                return;
            }
            if (frm.doc.tds_series_counter === undefined || frm.doc.tds_series_counter === null) {
                frappe.msgprint(__('Series Counter is required'));
                return;
            }

            // Extract all digits from naming series (e.g., "1707" from "TDS-1707")
            const allDigits = frm.doc.name.replace(/\D/g, '');
            
            // Validate we have at least 4 digits
            if (allDigits.length < 4) {
                frappe.msgprint(__('Naming Series must contain at least 4 digits', allDigits));
                return;
            }

            // Get last 4 digits
            const last_four = allDigits.slice(-4);

            // Generate current date components
            const today = new Date();
            const yy = today.getFullYear().toString().slice(-2);
            const mm = String(today.getMonth() + 1).padStart(2, '0');
            const dd = String(today.getDate()).padStart(2, '0');

            // Create version string
            const version = `V${frm.doc.tds_version_counter}-${frm.doc.item_code}-Date:${yy}/${mm}/${dd}*${frm.doc.tds_series_counter}${last_four}`;

            // Update the field and show success
            frm.set_value('tds_naming_series', version);
            frappe.show_alert({
                message: __('Version generated successfully'),
                indicator: 'green'
            });
        }).addClass('btn-primary');
    }
});

frappe.ui.form.on('TDS Product Specification', {
    refresh: function(frm) {
        // Add button to fetch TDS version
        frm.add_custom_button(__('Fetch TDS Version'), function() {
            fetchFilteredTdsVersion(frm);
        }).addClass('btn-primary');
    }
});

function fetchFilteredTdsVersion(frm) {
    // Validate we have an item code to filter by
    if (!frm.doc.item_code) {
        frappe.msgprint(__('Please select an Item Code first'));
        return;
    }

    // Validate we have a TDS Settings link
    if (!frm.doc.tds_settings) {
        frappe.msgprint(__('Please select a TDS Settings document first'));
        return;
    }

    frappe.call({
        method: 'frappe.client.get_value',
        args: {
            doctype: 'TDS Settings',
            filters: {
                name: frm.doc.tds_settings,
                item_code: frm.doc.item_code  // This ensures we only match the correct product
            },
            fieldname: ['tds_naming_series']
        },
        callback: function(r) {
            if (r.message && r.message.tds_naming_series) {
                frm.set_value('version', r.message.tds_naming_series);
                frappe.show_alert(__('TDS Version fetched successfully'));
            } else {
                frappe.msgprint(__('No matching TDS Version found for this product'));
            }
        }
    });
}

/**
 * COA AMB Validation Client Script - FIXED
 * 
 * Fixes Applied:
 * 1. Field name corrected: parameter → parameter_name
 * 2. Field name corrected: result_value → result
 * 3. Added null check for grid_row.$row to prevent TypeError
 * 
 * Original bug: "TypeError: Cannot read properties of undefined (reading 'removeClass')"
 */

frappe.ui.form.on('COA AMB', {
    refresh: function(frm) {
        if(!frm.is_new()) {
            frm.add_custom_button(__('Validate All Results'), function() {
                validate_all_results(frm);
            }).addClass('btn-primary');
        }
        
        apply_validation_styles();
        setup_existing_rows_validation(frm);
    },
    
    onload: function(frm) {
        setup_parameter_validation(frm);
    },
    
    coa_quality_test_parameter: function(frm) {
        setup_existing_rows_validation(frm);
    }
});

function setup_parameter_validation(frm) {
    frappe.ui.form.on('COA Quality Test Parameter', {
        result: function(frm, cdt, cdn) {
            const row = frappe.get_doc(cdt, cdn);
            setTimeout(function() {
                validate_parameter_row(frm, row);
                frm.refresh_field('coa_quality_test_parameter');
            }, 300);
        },
        
        refresh_field: function(frm, cdt, cdn) {
            apply_row_styling(frm, cdt, cdn);
        }
    });
}

function setup_existing_rows_validation(frm) {
    if (frm.doc.coa_quality_test_parameter) {
        frm.doc.coa_quality_test_parameter.forEach(function(row) {
            apply_row_styling_by_doc(frm, row);
        });
    }
}

function apply_validation_styles() {
    if (document.getElementById('coa-validation-styles')) return;
    
    const style = document.createElement('style');
    style.id = 'coa-validation-styles';
    style.textContent = `
        .grid-row[data-fieldname="coa_quality_test_parameter"] .result-pass { 
            background-color: #e6f7e6 !important; 
        }
        .grid-row[data-fieldname="coa_quality_test_parameter"] .result-fail { 
            background-color: #ffe6e6 !important; 
        }
        .grid-row[data-fieldname="coa_quality_test_parameter"] .result-na { 
            background-color: #f5f5f5 !important; 
        }
    `;
    document.head.appendChild(style);
}

function apply_row_styling(frm, cdt, cdn) {
    const row = frappe.get_doc(cdt, cdn);
    apply_row_styling_by_doc(frm, row);
}

function apply_row_styling_by_doc(frm, row) {
    try {
        const grid = frm.fields_dict.coa_quality_test_parameter.grid;
        
        if (!grid) return;
        if (!grid.grid_rows_by_docname) return;
        if (!grid.grid_rows_by_docname[row.name]) return;
        
        const grid_row = grid.grid_rows_by_docname[row.name];
        
        // FIXED: Null check for grid_row.$row to prevent TypeError
        if (!grid_row || !grid_row.$row) {
            console.warn('COA Validation: Grid row $row DOM element not found for:', row.name);
            return;
        }
        
        grid_row.$row.removeClass('result-pass result-fail result-na');
        
        if (row.status === 'Pass' || row.status === 'PASS') {
            grid_row.$row.addClass('result-pass');
        } else if (row.status === 'Fail' || row.status === 'FAIL') {
            grid_row.$row.addClass('result-fail');
        } else if (row.status === 'N/A' || row.status === 'NA') {
            grid_row.$row.addClass('result-na');
        }
    } catch(e) {
        console.error('COA Validation: Error applying row styling:', e);
    }
}

function validate_parameter_row(frm, row) {
    // FIXED: Use result instead of result_value
    if (!row.result && row.result !== 0) {
        return null;
    }

    // Check if this is a numeric parameter
    if (row.numeric) {
        const result = parseFloat(row.result);
        
        if (isNaN(result)) {
            frappe.model.set_value(row.doctype, row.name, 'status', 'Fail');
            return false;
        }

        const min = parseFloat(row.min_value) || 0;
        const max = parseFloat(row.max_value) || Infinity;

        if (result >= min && result <= max) {
            frappe.model.set_value(row.doctype, row.name, 'status', 'Pass');
            return true;
        } else {
            frappe.model.set_value(row.doctype, row.name, 'status', 'Fail');
            return false;
        }
    } else {
        // Non-numeric validation
        const result = (row.result || '').toString().toUpperCase().trim();
        
        // ============================================
        // FIX: Special handling for "None" values (Preservatives, etc.)
        // ============================================
        // Check if the parameter expects "None" as a valid result
        const expectsNone = row.parameter_name && 
            (row.parameter_name.toLowerCase().includes('preservative') ||
             row.parameter_name.toLowerCase().includes('none') ||
             row.expected_value === 'None' ||
             row.expected_value === 'NONE');
        
        // If "None" is expected and result is "None" (any case), treat as PASS
        if (expectsNone && (result === 'NONE' || result === 'N/A' || result === 'NA')) {
            frappe.model.set_value(row.doctype, row.name, 'status', 'Pass');
            return true;
        }
        
        // Standard validation
        if (result === 'PASS' || result === 'YES' || result === 'TRUE' || result === 'OK' || result === 'NEGATIVE') {
            frappe.model.set_value(row.doctype, row.name, 'status', 'Pass');
            return true;
        } else if (result === 'FAIL' || result === 'NO' || result === 'FALSE' || result === 'NOT OK') {
            frappe.model.set_value(row.doctype, row.name, 'status', 'Fail');
            return false;
        } else {
            frappe.model.set_value(row.doctype, row.name, 'status', 'N/A');
            return null;
        }
    }
}

function validate_all_results(frm) {
    if (!frm.doc.coa_quality_test_parameter || frm.doc.coa_quality_test_parameter.length === 0) {
        frappe.msgprint(__('No test parameters found'));
        return;
    }

    let allValid = true;
    let passedCount = 0;
    let failedCount = 0;
    let naCount = 0;
    let emptyCount = 0;
    let totalTests = 0;
    let testedTests = 0;

    frm.doc.coa_quality_test_parameter.forEach(function(row) {
        if (row.custom_is_title_row) return;
        totalTests++;
        if (row.result || row.result === 0) {
            testedTests++;
            const isValid = validate_parameter_row(frm, row);
            if (isValid === true) passedCount++;
            if (isValid === false) {
                failedCount++;
                allValid = false;
            }
            if (isValid === null) naCount++;
        } else {
            emptyCount++;
        }
    });

    frm.refresh_field('coa_quality_test_parameter');

    let passPercentage = 0;
    let testedPercentage = 0;
    
    if (totalTests > 0) {
        passPercentage = (passedCount / totalTests) * 100;
        testedPercentage = (testedTests / totalTests) * 100;
    }

    let overallResult = 'Pending';
    let complianceStatus = 'Pending';
    
    if (failedCount > 0) {
        overallResult = 'Fail';
        complianceStatus = 'Non-Compliant';
    } else if (emptyCount > 0 && passedCount > 0) {
        overallResult = 'Partial';
        complianceStatus = 'Under Review';
    } else if (passedCount > 0 && emptyCount === 0) {
        overallResult = 'Pass';
        complianceStatus = 'Compliant';
    } else if (totalTests === 0) {
        overallResult = 'No Tests';
    }

    frm.set_value('overall_result', overallResult);
    frm.set_value('compliance_status', complianceStatus);
    frm.set_value('pass_percentage', passPercentage);
    frm.set_value('tested_percentage', testedPercentage);
    
    frm.save();

    let message = __(`Validation: ${passedCount} PASS, ${failedCount} FAIL`);
    if (naCount > 0) message += __(`, ${naCount} N/A`);
    if (emptyCount > 0) message += __(`, ${emptyCount} Empty`);
    message += __(`\n\nOverall: ${overallResult} | Compliance: ${complianceStatus}`);
    message += __(`\nPass: ${passPercentage.toFixed(2)}% | Tested: ${testedPercentage.toFixed(2)}%`);

    frappe.msgprint({
        title: __('Validation Results'),
        indicator: allValid ? 'green' : 'red',
        message: message
    });

    return allValid;
}

frappe.ui.form.on('COA AMB', {
    refresh: function(frm) {
        // Add button to load TDS parameters via API
        frm.add_custom_button(__('Load TDS Parameters'), function() {
