    // Auto-load when TDS is selected for new documents
    linked_tds: function(frm) {
        if (frm.doc.linked_tds && frm.is_new()) {
            load_tds_parameters_via_api(frm);
        }
    },
    
    onload: function(frm) {
        setup_parameter_validation(frm);
    },
    
    coa_quality_test_parameter: function(frm) {
        setup_existing_rows_validation(frm);
    }
});

// API function to load TDS parameters
function load_tds_parameters_via_api(frm) {
    if (!frm.doc.linked_tds) {
        frappe.msgprint(__('Please select a TDS first'));
        return;
    }
    
    if (!frm.doc.name) {
        frappe.msgprint(__('Please save the document first'));
        return;
    }
    
    frappe.call({
        method: 'coa_amb_api',
        args: {
            coa_name: frm.doc.name,
            tds_name: frm.doc.linked_tds
        },
        callback: function(r) {
            if (!r.exc) {
                if (r.message.success) {
                    frappe.msgprint(__('✅ ') + r.message.message);
                    frm.refresh();
                } else {
                    frappe.msgprint(__('❌ ') + r.message.message);
                }
            } else {
                frappe.msgprint(__('Error calling API: ') + r.exc);
            }
        },
        freeze: true,
        freeze_message: __('Loading parameters from TDS...')
    });
}

