function validate_tds_compliance_fixed(frm) {
    console.log('=== STARTING TDS COMPLIANCE VALIDATION ===');
    
    if (!frm.doc.coa_quality_test_parameter || frm.doc.coa_quality_test_parameter.length === 0) {
        frappe.msgprint(__('No parameters to validate'));
        return;
    }
    
    // CRITICAL: Force refresh all form data before validation
    frm.refresh_fields();
    
    // Get fresh data from the grid
    var grid = frm.fields_dict.coa_quality_test_parameter.grid;
    var current_data = [];
    
    if (grid && grid.grid_rows) {
        grid.grid_rows.forEach(function(grid_row, index) {
            if (grid_row.doc) {
                current_data.push(grid_row.doc);
            }
        });
    } else {
        current_data = frm.doc.coa_quality_test_parameter;
    }
    
    console.log('Total parameters to validate:', current_data.length);
    
    var validation_results = {
        total: current_data.length,
        passed: 0,
        failed: 0,
        pending: 0,
        skipped: 0,
        title_rows: 0,
        issues: []
    };
    
    current_data.forEach(function(param, index) {
        console.log('\n--- Validating Row ' + (index + 1) + ': ' + param.parameter + ' ---');
        console.log('Raw data:', {
            parameter: param.parameter,
            result_value: param.result_value,
            min_value: param.min_value,
            max_value: param.max_value,
            numeric: param.numeric,
            specification: param.specification
        });
        
        // Skip title rows
        if (is_title_row(param)) {
            console.log('Skipping title row');
            validation_results.skipped++;
            validation_results.title_rows++;
            
            // Set result text to empty for title rows
            param.result_text = '';
            param.result_status = 'N/A';
            
            return;
        }
        
        var result = validate_parameter_compliance_fixed(param, index);
        console.log('Validation result:', result);
        
        if (result.status === 'PASS') validation_results.passed++;
        else if (result.status === 'FAIL') validation_results.failed++;
        else validation_results.pending++;
        
        if (result.issues.length > 0) {
            validation_results.issues = validation_results.issues.concat(result.issues);
        }
        
        // Update the parameter result
        param.result_text = result.status;
        update_parameter_result(frm, param, result.status);
    });
    
    console.log('=== VALIDATION COMPLETE ===');
    console.log('Results:', validation_results);
    
    // Update the document validation status
    update_document_validation_status(frm, validation_results);
    
    // Refresh the form after updating results
    frm.refresh_field('coa_quality_test_parameter');
    
    show_compliance_results(validation_results, frm);
}

