// =====================
// REAL-TIME VALIDATION SETUP
// =====================

function setup_real_time_validation(frm) {
    initialize_validation_styles();
    
    frappe.ui.form.on('COA Quality Test Parameter', {
        result: function(frm, cdt, cdn) {
            setTimeout(function() {
                perform_real_time_validation_for_row(frm, cdt, cdn);
            }, 200);
        }
    });
}

function perform_real_time_validation_for_row(frm, cdt, cdn) {
    var row = locals[cdt][cdn];
    if (!row) return;
    if (row.is_title_row) return;
    if (!row.result && row.result !== 0) {
        clear_validation_styling(cdn);
        return;
    }
    
    var acceptanceCriteria = (row.value || row.specification || '').toString();
    var resultStr = row.result.toString().toUpperCase().trim();
    var isValid = false;
    var status = 'Pending';
    
    // HIGHEST PRIORITY: "PASS" should always mean PASS
    if (resultStr === 'PASS') {
        isValid = true;
        status = 'Pass';
    }
    else if (acceptanceCriteria.toUpperCase().includes('NEGATIVE')) {
        if (resultStr === 'NEGATIVE' || resultStr === 'NEG' || resultStr === 'NONE' || resultStr === '0') {
            isValid = true;
            status = 'Pass';
        } else {
            isValid = false;
            status = 'Fail';
        }
    }
    else if (acceptanceCriteria.toUpperCase().includes('NONE')) {
        if (resultStr === 'NONE' || resultStr === '0') {
            isValid = true;
            status = 'Pass';
        } else {
            isValid = false;
            status = 'Fail';
        }
    }
    else if (row.numeric || (row.min_value !== null && row.min_value !== undefined && row.min_value !== '') || 
             (row.max_value !== null && row.max_value !== undefined && row.max_value !== '')) {
        var resultNum = parseFloat(resultStr);
        var minNum = (row.min_value !== null && row.min_value !== undefined && row.min_value !== '') ? parseFloat(row.min_value) : null;
        var maxNum = (row.max_value !== null && row.max_value !== undefined && row.max_value !== '') ? parseFloat(row.max_value) : null;
        
        if (isNaN(resultNum)) {
            isValid = false;
            status = 'Fail';
        } else {
            var withinMin = (minNum === null || resultNum >= minNum);
            var withinMax = (maxNum === null || resultNum <= maxNum);
            isValid = withinMin && withinMax;
            status = isValid ? 'Pass' : 'Fail';
        }
    }
    else if (acceptanceCriteria && acceptanceCriteria.trim() !== '') {
        if (resultStr === acceptanceCriteria.toUpperCase().trim()) {
            isValid = true;
            status = 'Pass';
        } else {
            isValid = false;
            status = 'Fail';
        }
    }
    else {
        isValid = true;
        status = 'Pass';
    }
    
    frappe.model.set_value(cdt, cdn, 'status', status);
    apply_validation_styling(cdn, status);
}

function clear_validation_styling(cdn) {
    var row_element = $('div[data-name="' + cdn + '"]');
    if (row_element.length > 0) {
        row_element.find('[data-fieldname="result"] input').removeClass('validation-pass validation-fail');
    }
}

function apply_validation_styling(cdn, status) {
    var row_element = $('div[data-name="' + cdn + '"]');
    if (row_element.length === 0) return;
    
    var result_input = row_element.find('[data-fieldname="result"] input');
    if (result_input.length === 0) return;
    
    result_input.removeClass('validation-pass validation-fail');
    
    if (status === 'Pass') {
        result_input.addClass('validation-pass');
    } else if (status === 'Fail') {
        result_input.addClass('validation-fail');
    }
}

function initialize_validation_styles() {
    if ($('#coa-validation-styles').length) return;
    
    $('<style id="coa-validation-styles">')
        .prop('type', 'text/css')
        .html(`
            .frappe-control[data-fieldname="result"] input.validation-pass {
                background-color: #d4edda !important;
                border-color: #28a745 !important;
            }
            .frappe-control[data-fieldname="result"] input.validation-fail {
                background-color: #f8d7da !important;
                border-color: #dc3545 !important;
            }
        `)
        .appendTo('head');
}

// =====================
// LOAD TDS PARAMETERS
// =====================

function load_tds_parameters_enhanced(frm) {
    if (!frm.doc.linked_tds) {
        frappe.msgprint({
            title: __('TDS Required'),
            message: __('Please select a TDS Product Specification first'),
            indicator: 'red'
        });
        return;
    }
    
    if (frm.is_new() && !frm.doc.name) {
        frappe.confirm(__('Document must be saved before loading parameters. Save now?'), function() {
            frm.save().then(function() {
                execute_parameter_loading(frm);
            });
        });
        return;
    }
    
    execute_parameter_loading(frm);
}

function execute_parameter_loading(frm) {
    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'TDS Product Specification',
            name: frm.doc.linked_tds
        },
        callback: function(r) {
            if (r.message) {
                process_tds_parameters(r.message, frm);
                frappe.show_alert({
                    message: __('✅ Successfully loaded parameters from TDS'),
                    indicator: 'green'
                });
            } else {
                frappe.msgprint({
                    title: __('Loading Failed'),
                    message: __('Could not load TDS parameters'),
                    indicator: 'red'
                });
            }
        }
    });
}

function process_tds_parameters(tds_doc, frm) {
    if (!tds_doc.item_quality_inspection_parameter || tds_doc.item_quality_inspection_parameter.length === 0) {
        frappe.msgprint({
            title: __('No Parameters'),
            message: __('No parameters found in the selected TDS'),
            indicator: 'orange'
        });
        return;
    }
    
    frm.clear_table('coa_quality_test_parameter');
    
    tds_doc.item_quality_inspection_parameter.forEach(function(tds_param) {
        var row = frm.add_child('coa_quality_test_parameter');
        row.parameter_name = tds_param.parameter || tds_param.specification || 'Parameter';
        row.specification = tds_param.value || '';
        row.test_method = tds_param.custom_method || '';
        row.value = tds_param.value || '';
        row.custom_uom = tds_param.custom_uom || '';
        row.numeric = tds_param.numeric || 0;
        row.min_value = (tds_param.min_value !== null && tds_param.min_value !== undefined && tds_param.min_value !== '') ? tds_param.min_value : null;
        row.max_value = (tds_param.max_value !== null && tds_param.max_value !== undefined && tds_param.max_value !== '') ? tds_param.max_value : null;
        row.parameter_group = tds_param.parameter_group || '';
        row.is_title_row = tds_param.is_title_row || 0;
        row.status = 'Pending';
        row.result = '';
    });
    
    frm.refresh_field('coa_quality_test_parameter');
}

// =====================
// BUTTON 2: VALIDATE TDS COMPLIANCE
// =====================

function validate_tds_compliance_fixed(frm) {
    if (!frm.doc.coa_quality_test_parameter || frm.doc.coa_quality_test_parameter.length === 0) {
        frappe.msgprint(__('No parameters to validate'));
        return;
    }
    
    frm.refresh_fields();
    
    var results = {
        total: 0,
        passed: 0,
        failed: 0,
        pending: 0,
        title_rows: 0,
        issues: []
    };
    
    frm.doc.coa_quality_test_parameter.forEach(function(param, index) {
        if (param.is_title_row) {
            results.title_rows++;
            return;
        }
        
        results.total++;
        
        if (!param.result && param.result !== 0) {
            results.pending++;
            results.issues.push('Row ' + (index + 1) + ': ⏳ No result value entered');
            frappe.model.set_value(param.doctype, param.name, 'status', 'Pending');
            return;
        }
        
        var acceptanceCriteria = (param.value || param.specification || '').toString();
        var resultStr = param.result.toString().toUpperCase().trim();
        var isValid = false;
        
        if (resultStr === 'PASS') {
            isValid = true;
        }
        else if (acceptanceCriteria.toUpperCase().includes('NEGATIVE')) {
            isValid = (resultStr === 'NEGATIVE' || resultStr === 'NEG' || resultStr === 'NONE' || resultStr === '0');
        }
        else if (acceptanceCriteria.toUpperCase().includes('NONE')) {
            isValid = (resultStr === 'NONE' || resultStr === '0');
        }
        else if (param.numeric || (param.min_value !== null && param.min_value !== undefined && param.min_value !== '') || 
                 (param.max_value !== null && param.max_value !== undefined && param.max_value !== '')) {
            var resultNum = parseFloat(resultStr);
            var minNum = (param.min_value !== null && param.min_value !== undefined && param.min_value !== '') ? parseFloat(param.min_value) : null;
            var maxNum = (param.max_value !== null && param.max_value !== undefined && param.max_value !== '') ? parseFloat(param.max_value) : null;
            
            if (!isNaN(resultNum)) {
                var withinMin = (minNum === null || resultNum >= minNum);
                var withinMax = (maxNum === null || resultNum <= maxNum);
                isValid = withinMin && withinMax;
            } else {
                isValid = false;
            }
        }
        else if (acceptanceCriteria && acceptanceCriteria.trim() !== '') {
            isValid = (resultStr === acceptanceCriteria.toUpperCase().trim());
        }
        else {
            isValid = true;
        }
        
        if (isValid) {
            results.passed++;
            frappe.model.set_value(param.doctype, param.name, 'status', 'Pass');
        } else {
            results.failed++;
            results.issues.push('Row ' + (index + 1) + ': ❌ "' + resultStr + '" vs "' + acceptanceCriteria + '"');
            frappe.model.set_value(param.doctype, param.name, 'status', 'Fail');
        }
    });
    
    frm.refresh_field('coa_quality_test_parameter');
    frm.save();
    
    var overallStatus = results.failed === 0 && results.passed > 0 ? 'Compliant' : 
                        (results.pending > 0 && results.failed === 0 ? 'Pending Review' : 'Non-Compliant');
    var passPct = results.total > 0 ? (results.passed / results.total) * 100 : 0;
    
    var message = '<div style="margin: 10px 0;">';
    message += '<div style="text-align: center;"><h2>' + overallStatus + '</h2></div>';
    message += '<div style="display: flex; gap: 15px; margin-bottom: 20px;">';
    message += '<div style="flex:1; background:#d4edda; border-radius:8px; padding:15px; text-align:center;"><div style="font-size:32px; font-weight:bold;">' + results.passed + '</div><div>✅ PASS</div></div>';
    message += '<div style="flex:1; background:#f8d7da; border-radius:8px; padding:15px; text-align:center;"><div style="font-size:32px; font-weight:bold;">' + results.failed + '</div><div>❌ FAIL</div></div>';
    message += '<div style="flex:1; background:#fff3cd; border-radius:8px; padding:15px; text-align:center;"><div style="font-size:32px; font-weight:bold;">' + results.pending + '</div><div>⏳ PENDING</div></div>';
    message += '</div>';
    message += '<table style="width:100%;"></tr><td>📊 Total:</td><td style="text-align:right;">' + results.total + '</td></tr>';
    message += '<tr><td>📋 Title Rows:</td><td style="text-align:right;">' + results.title_rows + '</td></tr>';
    message += '<tr><td>📈 Pass %:</td><td style="text-align:right; color:green;">' + passPct.toFixed(2) + '%</td></tr>';
    message += '</table>';
    
    if (results.issues.length > 0) {
        message += '<div style="background:#f8d7da; border-radius:8px; padding:10px; margin-top:10px;"><h5>⚠️ Issues:</h5><ul>';
        results.issues.forEach(function(issue) { message += '<li>' + issue + '</li>'; });
        message += '</ul></div>';
    }
    
    message += '<hr><div style="text-align:center;"><button class="btn btn-default btn-sm" onclick="cur_dialog && cur_dialog.hide()">Close</button></div>';
    message += '</div>';
    
    frappe.msgprint({ title: __('TDS Compliance Results'), message: message, indicator: overallStatus === 'Compliant' ? 'green' : 'red', width: 450 });
}

