function audit_tds_compliance(frm) {
    if (!frm.doc.coa_quality_test_parameter || frm.doc.coa_quality_test_parameter.length === 0) {
        frappe.msgprint(__('No parameters to audit'));
        return;
    }
    
    frm.refresh_fields();
    
    var audit = { total: 0, passed: 0, failed: 0, pending: 0, title_rows: 0, details: [] };
    
    frm.doc.coa_quality_test_parameter.forEach(function(param, idx) {
        if (param.is_title_row) {
            audit.title_rows++;
            audit.details.push({ row: idx+1, parameter: param.parameter, status: 'TITLE', message: 'Title row' });
            return;
        }
        
        audit.total++;
        
        if (!param.result && param.result !== 0) {
            audit.pending++;
            audit.details.push({ row: idx+1, parameter: param.parameter, result: '', acceptance: param.value || param.specification, status: 'PENDING', message: 'No result entered' });
            return;
        }
        
        var acceptance = (param.value || param.specification || '').toString();
        var resultStr = param.result.toString().toUpperCase().trim();
        var isValid = false;
        
        if (resultStr === 'PASS') {
            isValid = true;
        }
        else if (acceptance.toUpperCase().includes('NEGATIVE')) {
            isValid = (resultStr === 'NEGATIVE' || resultStr === 'NEG' || resultStr === 'NONE' || resultStr === '0');
        }
        else if (acceptance.toUpperCase().includes('NONE')) {
            isValid = (resultStr === 'NONE' || resultStr === '0');
        }
        else if (param.numeric || (param.min_value !== null && param.min_value !== undefined && param.min_value !== '') || 
                 (param.max_value !== null && param.max_value !== undefined && param.max_value !== '')) {
            var num = parseFloat(resultStr);
            var minNum = (param.min_value !== null && param.min_value !== undefined && param.min_value !== '') ? parseFloat(param.min_value) : null;
            var maxNum = (param.max_value !== null && param.max_value !== undefined && param.max_value !== '') ? parseFloat(param.max_value) : null;
            if (!isNaN(num)) {
                var withinMin = (minNum === null || num >= minNum);
                var withinMax = (maxNum === null || num <= maxNum);
                isValid = withinMin && withinMax;
            } else { isValid = false; }
        }
        else if (acceptance && acceptance.trim() !== '') {
            isValid = (resultStr === acceptance.toUpperCase().trim());
        }
        else { isValid = true; }
        
        if (isValid) {
            audit.passed++;
            audit.details.push({ row: idx+1, parameter: param.parameter, result: param.result, acceptance: acceptance, status: 'PASS', message: '✅ Matches criteria' });
        } else {
            audit.failed++;
            audit.details.push({ row: idx+1, parameter: param.parameter, result: param.result, acceptance: acceptance, status: 'FAIL', message: '❌ Expected: "' + acceptance + '", Got: "' + param.result + '"' });
        }
    });
    
    var passPct = audit.total > 0 ? (audit.passed / audit.total) * 100 : 0;
    var overall = audit.failed === 0 && audit.passed > 0 ? 'PASS' : (audit.pending > 0 && audit.failed === 0 ? 'PARTIAL' : 'FAIL');
    
    var message = '<div style="margin:10px 0;"><h3 style="text-align:center;">📋 COA Compliance Audit Report</h3><hr>';
    message += '<div style="display:flex; gap:15px; margin-bottom:20px;">';
    message += '<div style="flex:1; background:#d4edda; border-radius:8px; padding:12px; text-align:center;"><div style="font-size:28px; font-weight:bold;">' + audit.passed + '</div><div>✅ PASS</div></div>';
    message += '<div style="flex:1; background:#f8d7da; border-radius:8px; padding:12px; text-align:center;"><div style="font-size:28px; font-weight:bold;">' + audit.failed + '</div><div>❌ FAIL</div></div>';
    message += '<div style="flex:1; background:#fff3cd; border-radius:8px; padding:12px; text-align:center;"><div style="font-size:28px; font-weight:bold;">' + audit.pending + '</div><div>⏳ PENDING</div></div>';
    message += '</div>';
    message += '<div style="background:#e9ecef; border-radius:8px; padding:10px; margin-bottom:20px; text-align:center;"><strong>📊 Pass Percentage:</strong> <span style="font-size:20px; color:#28a745;">' + passPct.toFixed(2) + '%</span></div>';
    
    message += '<h4>🔍 Detailed Parameter Audit</h4>';
    message += '<div style="max-height:400px; overflow-y:auto; border:1px solid #ddd; border-radius:4px;">';
    message += '<table style="width:100%; border-collapse:collapse; font-size:11px;">';
    message += '<thead><tr style="background-color:#2c3e50; color:white; position:sticky; top:0;">';
    message += '<th style="padding:8px;">#</th><th style="padding:8px;">Parameter</th><th style="padding:8px;">Result</th>';
    message += '<th style="padding:8px;">Acceptance Criteria</th><th style="padding:8px;">Status</th><th style="padding:8px;">Message</th>';
    message += '</tr></thead><tbody>';
    
    audit.details.forEach(function(d) {
        var bgColor = d.status === 'PASS' ? '#d4edda' : (d.status === 'FAIL' ? '#f8d7da' : (d.status === 'PENDING' ? '#fff3cd' : '#e9ecef'));
        var statusText = d.status === 'PASS' ? '✅ PASS' : (d.status === 'FAIL' ? '❌ FAIL' : (d.status === 'PENDING' ? '⏳ PENDING' : '📋 TITLE'));
        message += '<tr style="background-color:' + bgColor + ';">';
        message += '<td style="padding:6px; text-align:center;">' + d.row + '</td>';
        message += '<td style="padding:6px;">' + (d.parameter || '—') + '</td>';
        message += '<td style="padding:6px;">' + (d.result || '—') + '</td>';
        message += '<td style="padding:6px;">' + (d.acceptance || '—') + '</td>';
        message += '<td style="padding:6px; text-align:center; font-weight:bold;">' + statusText + '</td>';
        message += '<td style="padding:6px;">' + (d.message || '—') + '</td>';
        message += '</tr>';
    });
    
    message += '</tbody></table></div><hr>';
    message += '<div style="text-align:center;"><button class="btn btn-default btn-sm" onclick="cur_dialog && cur_dialog.hide()">Close</button></div>';
    message += '</div>';
    
    frappe.msgprint({ title: __('COA Compliance Audit'), message: message, indicator: overall === 'PASS' ? 'green' : (overall === 'PARTIAL' ? 'orange' : 'red'), width: 1000 });
}

