// BUTTON 4: SUBMIT COA (FIXED)
// =====================

function submit_coa_document(frm) {
    frappe.confirm(
        __('Are you sure you want to submit this COA? This will start the approval workflow.'),
        function() {
            frappe.show_alert({ message: __('Starting workflow...'), indicator: 'blue' });
            
            // Obtener el estado actual del workflow
            var current_state = frm.doc.workflow_state_1 || 'Draft';
            
            // Definir las acciones según el estado actual
            var action = '';
            
            if (current_state === 'Draft') {
                action = 'Review';
            } else if (current_state === 'Validated') {
                action = 'Submit for Supervisor Approval';
            } else if (current_state === 'Pending Supervisor') {
                action = 'Approve';
            } else if (current_state === 'Approved') {
                action = 'Submit for Sales Approval';
            } else {
                // Si ya está en un estado avanzado, usar submit directo
                frm.savesubmit();
                return;
            }
            
            // Ejecutar la acción del workflow
            frappe.call({
