/**
 * Client Script for Quotation - Escalated Quotation Automation
 * 
 * Purpose: Automatically populate the "Quotation Item Escalated" child table
 * based on selected items and shipping rule weight ranges
 * 
 * Formula: Rate = 40 USD * Quantity(Kg) / (Quantity(Kg) - 100 USD)
 */

frappe.ui.form.on('Quotation', {
    // Refresh event - set up event listeners
    refresh: function(frm) {
        // Only process if shipping rule is selected
        if (frm.doc.shipping_rule || frm.doc.custom_freigh_shipment_rule) {
            calculate_escalated_quotation(frm);
        }
    },

    // When shipping rule changes, recalculate escalated quotation
    shipping_rule: function(frm) {
        calculate_escalated_quotation(frm);
    },

    custom_freigh_shipment_rule: function(frm) {
        // When custom freight shipment rule is selected, copy to shipping_rule
        if (frm.doc.custom_freigh_shipment_rule) {
            frm.set_value('shipping_rule', frm.doc.custom_freigh_shipment_rule);
        }
        calculate_escalated_quotation(frm);
    }
});

// When items are added or changed
frappe.ui.form.on('Quotation Item', {
    items_add: function(frm, cdt, cdn) {
        calculate_escalated_quotation(frm);
    },

    items_remove: function(frm, cdt, cdn) {
        calculate_escalated_quotation(frm);
    },

    item_code: function(frm, cdt, cdn) {
        calculate_escalated_quotation(frm);
    },

    qty: function(frm, cdt, cdn) {
        calculate_escalated_quotation(frm);
    }
});

/**
 * Calculate and populate escalated quotation child table
 */
function calculate_escalated_quotation(frm) {
    if (!frm.doc.shipping_rule && !frm.doc.custom_freigh_shipment_rule) {
        console.log('No shipping rule selected, skipping escalated quotation calculation');
        return;
    }

    const shipping_rule = frm.doc.shipping_rule || frm.doc.custom_freigh_shipment_rule;

    // Get shipping rule details to fetch weight ranges
    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'Shipping Rule',
            name: shipping_rule
        },
        callback: function(r) {
            if (r.message && r.message.conditions) {
                const weight_ranges = r.message.conditions;
                populate_escalated_table(frm, weight_ranges);
            }
        }
    });
}

/**
 * Populate the escalated quotation child table with items and calculated rates
 */
function populate_escalated_table(frm, weight_ranges) {
    // Clear existing escalated quotation items
    frm.clear_table('custom_quotation_child_table');

    // Get all items from the quotation
    const items = frm.doc.items || [];

    if (items.length === 0) {
        console.log('No items in quotation');
        return;
    }

    // For each item in the quotation
    items.forEach(function(item) {
        // For each weight range in the shipping rule
        weight_ranges.forEach(function(range) {
            const from_qty = range.from_value || 0;
            const to_qty = range.to_value || 999999;
            const mid_qty = (from_qty + to_qty) / 2;  // Use midpoint of range

            // Calculate rate using formula: 40 USD * Qty(Kg) / (Qty(Kg) - 100 USD)
            let calculated_rate = 0;
            if (mid_qty > 100) {
                // Formula: 40 * Qty / (Qty - 100)
                calculated_rate = (40 * mid_qty) / (mid_qty - 100);
            } else {
                // For quantities <= 100kg, use base rate
                calculated_rate = range.shipping_amount || 40;
            }

            // Add row to escalated quotation table
            const escalated_row = frm.add_child('custom_quotation_child_table');
            escalated_row.item_code = item.item_code;
            escalated_row.item_name = item.item_name;
            escalated_row.qty = mid_qty;  // Use midpoint quantity
            escalated_row.quantity_range = `${from_qty} - ${to_qty} kg`;  // Display range
            escalated_row.rate = calculated_rate;
            escalated_row.amount = mid_qty * calculated_rate;

            // Optional: Set the escalated rate and delivered price
            escalated_row.escalated_rate = calculated_rate;
            escalated_row.delivered_price = calculated_rate;
        });
    });

    // Refresh the child table
    frm.refresh_field('custom_quotation_child_table');

    frappe.show_alert({
        message: __('Escalated quotation calculated successfully'),
        indicator: 'green'
    }, 3);
}

/**
 * QUOTATION ESCALATED AUTOMATION - CORRECTED VERSION
 * 
 * Purpose: Calculate rates for items in the "Quotation Item Escalated" child table
 * 
 * Workflow:
 * 1. User selects Item Code → Fetch ex-works price from Item master
 * 2. User selects Quantity Range (e.g., "1 Kg", "5 Kg") → Extract numeric quantity
 * 3. Look up freight cost from parent Quotation's Shipping Rule based on quantity
 * 4. Calculate: Rate (per kg) = ex-works price + (freight_cost / quantity)
 * 5. Calculate: Delivered Price = ex-works price + freight_cost
 * 
 * Date: 2025-10-18 23:18
 * Fixed Issues:
 * - Removed incorrect formula (40 * Qty / (Qty - 100))
 * - Now uses actual shipping rule tier rates (70, 60, 50, 45, 40)
 * - Properly calculates per-kg rates
 */

frappe.ui.form.on('Quotation Item Escalated', {

    // When item is selected
    item_code: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        console.log('✅ Item selected:', row.item_code);

        if (row.item_code) {
            // Fetch ex-works price from Item master
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Item',
                    name: row.item_code
                },
                callback: function(r) {
                    if (r.message) {
                        const item = r.message;
                        // Use standard_rate or valuation_rate
                        const ex_works_price = item.standard_rate || item.valuation_rate || 0;

                        console.log(`📦 Fetched ex-works price for ${row.item_code}: $${ex_works_price}`);

                        // Set ex_works_price field
                        frappe.model.set_value(cdt, cdn, 'ex_works_price', ex_works_price)
                            .then(() => {
                                // If quantity is already selected, recalculate
                                if (row.quantity_range) {
                                    calculate_freight_and_rate(frm, cdt, cdn);
                                }
                            })
                            .catch(err => console.error('❌ Error setting ex_works_price:', err));
                    }
                },
                error: function(err) {
                    console.error('❌ Error fetching item:', err);
                }
            });
        }
    },

    // When quantity range is selected (e.g., "1 Kg", "5 Kg")
    quantity_range: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        console.log('✅ Quantity range selected:', row.quantity_range);

        if (row.quantity_range && row.item_code) {
            calculate_freight_and_rate(frm, cdt, cdn);
        }
    },

    // Allow manual override of freight_cost
    freight_cost: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        console.log('✅ Freight cost manually changed:', row.freight_cost);
        recalculate_rate_and_delivered(frm, cdt, cdn);
    },

    // Allow manual override of ex_works_price
    ex_works_price: function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        console.log('✅ Ex-works price manually changed:', row.ex_works_price);
        recalculate_rate_and_delivered(frm, cdt, cdn);
    }
});

/**
 * Calculate freight cost and rate based on shipping rule
 */
function calculate_freight_and_rate(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    const shipping_rule = frm.doc.shipping_rule || frm.doc.custom_shipping_rule_amb_;

    if (!shipping_rule) {
        console.warn('⚠️ No shipping rule selected on quotation');
        frappe.msgprint(__('Please select a Shipping Rule on the quotation first'));
        return;
    }

    if (!row.quantity_range) {
        console.warn('⚠️ No quantity range selected');
        return;
    }

    // Extract numeric quantity from quantity_range (e.g., "1 Kg" → 1, "5 Kg" → 5, "25-150 Kg" → 25)
    const qty = extract_quantity_from_range(row.quantity_range);

    if (!qty || qty <= 0) {
        console.error('❌ Invalid quantity extracted from range:', row.quantity_range);
        return;
    }

    console.log(`🔍 Fetching shipping rate for: ${shipping_rule}, Qty: ${qty} kg`);

    // Fetch shipping rule details
    frappe.call({
        method: 'frappe.client.get',
        args: {
            doctype: 'Shipping Rule',
            name: shipping_rule
        },
        callback: function(r) {
            if (r.message && r.message.conditions) {
                const conditions = r.message.conditions;

                // Find the matching tier
                let freight_rate_per_kg = 0;
                for (let condition of conditions) {
                    const from_val = parseFloat(condition.from_value);
                    const to_val = parseFloat(condition.to_value);
                    const rate = parseFloat(condition.shipping_amount);

                    // Check if qty falls within this range
                    if (qty > from_val && qty <= to_val) {
                        freight_rate_per_kg = rate;
                        console.log(`✅ Matched tier: ${from_val}-${to_val} kg = $${rate}/kg`);
                        break;
                    }
                }

                if (freight_rate_per_kg === 0) {
                    console.warn('⚠️ No matching freight rate found for quantity:', qty);
                    frappe.msgprint(__('No freight rate found for quantity {0} kg', [qty]));
                    return;
                }

                // Calculate total freight cost for this quantity
                const freight_cost = freight_rate_per_kg * qty;
                console.log(`💰 Freight cost: $${freight_rate_per_kg}/kg × ${qty} kg = $${freight_cost}`);

                // Get ex-works price
                const ex_works = parseFloat(row.ex_works_price) || 0;

                // Calculate rate per kg = ex_works + freight_rate_per_kg
                const rate_per_kg = ex_works + freight_rate_per_kg;

                // Calculate delivered price = ex_works + freight_cost
                const delivered_price = ex_works + freight_cost;

                console.log(`📊 Calculations:`);
                console.log(`   Ex-works: $${ex_works}/kg`);
                console.log(`   Freight rate: $${freight_rate_per_kg}/kg`);
                console.log(`   Rate (per kg): $${rate_per_kg}/kg`);
                console.log(`   Total freight: $${freight_cost}`);
                console.log(`   Delivered price: $${delivered_price}`);

                // Set all calculated fields
                frappe.model.set_value(cdt, cdn, 'qty', qty)
                    .then(() => frappe.model.set_value(cdt, cdn, 'freight_cost', freight_cost))
                    .then(() => frappe.model.set_value(cdt, cdn, 'rate', rate_per_kg))
                    .then(() => frappe.model.set_value(cdt, cdn, 'delivered_price', delivered_price))
                    .then(() => frappe.model.set_value(cdt, cdn, 'escalated_rate', rate_per_kg))
                    .then(() => {
                        // Set freight location if available
                        if (r.message.custom_applicable_country) {
                            return frappe.model.set_value(cdt, cdn, 'freight_location', r.message.custom_applicable_country);
                        }
                    })
                    .then(() => {
                        frappe.show_alert({
                            message: __('Calculated: Rate ${0}/kg, Freight ${1}', [rate_per_kg.toFixed(2), freight_cost.toFixed(2)]),
                            indicator: 'green'
                        }, 3);
                    })
                    .catch(err => console.error('❌ Error setting values:', err));

            } else {
                console.error('❌ No conditions found in shipping rule');
                frappe.msgprint(__('Shipping rule has no rate conditions defined'));
            }
        },
        error: function(err) {
            console.error('❌ Error fetching shipping rule:', err);
        }
    });
}

/**
 * Recalculate rate and delivered price when freight or ex-works is manually changed
 */
function recalculate_rate_and_delivered(frm, cdt, cdn) {
    const row = locals[cdt][cdn];
    const qty = parseFloat(row.qty) || 0;
    const ex_works = parseFloat(row.ex_works_price) || 0;
    const freight_cost = parseFloat(row.freight_cost) || 0;

    if (qty > 0) {
        // Calculate freight per kg
        const freight_per_kg = freight_cost / qty;

        // Calculate rate per kg = ex_works + freight_per_kg
        const rate_per_kg = ex_works + freight_per_kg;

        // Calculate delivered price = ex_works + freight_cost
        const delivered_price = ex_works + freight_cost;

        console.log(`🔄 Recalculated: Rate ${rate_per_kg}/kg, Delivered ${delivered_price}`);

        frappe.model.set_value(cdt, cdn, 'rate', rate_per_kg)
            .then(() => frappe.model.set_value(cdt, cdn, 'delivered_price', delivered_price))
            .then(() => frappe.model.set_value(cdt, cdn, 'escalated_rate', rate_per_kg))
            .catch(err => console.error('❌ Error recalculating:', err));
    }
}

/**
 * Extract numeric quantity from quantity_range string
 * Examples:
 *   "1 Kg" → 1
 *   "5 Kg" → 5
 *   "25-150 Kg" → 25 (use lower bound)
 *   "150+ Kg" → 150
 */
function extract_quantity_from_range(range_str) {
    if (!range_str) return 0;

    // Remove "Kg" and trim
    let cleaned = range_str.replace(/kg/gi, '').trim();

    // Check for range format (e.g., "25-150" or "25 - 150")
    if (cleaned.includes('-')) {
        const parts = cleaned.split('-');
        const lower = parseFloat(parts[0].trim());
        return isNaN(lower) ? 0 : lower;
    }

    // Check for "150+" format
    if (cleaned.includes('+')) {
        const num = parseFloat(cleaned.replace('+', '').trim());
        return isNaN(num) ? 0 : num;
    }

    // Simple number
    const num = parseFloat(cleaned);
    return isNaN(num) ? 0 : num;
}

