            console.log('   ✅ Freight rate found: $', freight_rate, '/kg');
            
            // RATE × WEIGHT CALCULATION
            const freight_amount = freight_rate * quantity;
            console.log('\n   🧮 RATE × WEIGHT CALCULATION:');
            console.log('      freight_rate =', freight_rate, '/kg');
            console.log('      quantity =', quantity, 'kg');
            console.log('      freight_amount = freight_rate × quantity');
            console.log('      freight_amount =', freight_rate, '×', quantity, '=', freight_amount);
            
            // Find the matching range for description
            let range_desc = quantity + ' kg';
            for (let i = 0; i < weight_ranges.length; i++) {
                const range = weight_ranges[i];
                const from_val = parseFloat(range.from_value || 0);
                const to_val = parseFloat(range.to_value || 999999);
                
                if (quantity > from_val && quantity <= to_val) {
                    range_desc = from_val + ' - ' + to_val + ' kg';
                    break;
                }
            }
            
            // Add freight as an ITEM
            console.log('\n   ➕ ADDING FREIGHT AS ITEM ROW:');
            console.log('      Item Code: Freight Cost');
            console.log('      Quantity: 1');
            console.log('      Rate: $' + freight_amount);
            
            // Remove existing freight items
            const items = frm.doc.items || [];
            const freight_items = items.filter(function(item) { return item.item_code === 'Freight Cost'; });
            
            console.log('      🗑️ Removing', freight_items.length, 'existing freight item(s)');
            
            freight_items.forEach(function(freight_item) {
                frappe.model.clear_doc(freight_item.doctype, freight_item.name);
            });
            
            // Clear the freight items from the array
            frm.doc.items = items.filter(function(item) { return item.item_code !== 'Freight Cost'; });
            frm.refresh_field('items');
            
            // Add new freight item at the end
            const freight_row = frm.add_child('items');
            const item_cdt = freight_row.doctype;
            const item_cdn = freight_row.name;
            
            console.log('      ✅ Adding new freight item row');
            
            // Set all fields using frappe.model.set_value
            frappe.model.set_value(item_cdt, item_cdn, 'item_code', 'Freight Cost');
            frappe.model.set_value(item_cdt, item_cdn, 'item_name', 'Freight Cost');
            frappe.model.set_value(item_cdt, item_cdn, 'description', 
                frm.doc.shipping_rule + ' - ' + range_desc + ' (' + quantity + ' kg × $' + freight_rate + '/kg = $' + freight_amount + ')');
            frappe.model.set_value(item_cdt, item_cdn, 'qty', 1);
