            console.log('\n   ✅ Freight added as item row with RATE × WEIGHT calculation');
            console.log('==========================================\n');
            
            frappe.show_alert({
                message: __('✅ Freight: {0} kg × ${1}/kg = ${2} {3}', 
                    [quantity, freight_rate.toFixed(2), freight_amount.toFixed(2), frm.doc.currency]),
                indicator: 'green'
            }, 5);
            
            // Release execution lock after a delay
            setTimeout(function() {
