            freeze: true,
            freeze_message: __('Creating Sample Request...'),
            callback: function(r) {
                if (!r.exc && r.message) {
                    frappe.set_route('Form', 'Sample Request AMB', r.message.name);
                    frappe.show_alert({message: __('Sample Request created successfully'), indicator: 'green'});
                }
            }
        });
    };
}

